import { Link } from 'react-router-dom';
import { useAuthContext } from '../hooks/useAuthContext';

const Home = () => {
  const { user } = useAuthContext();

  return (
    <div className="home">
      <h1>Welcome to the Cyber Awareness Toolkit{user ? `, ${user.email}` : ''}!</h1>
      <p>These tools are designed to help you stay safe online:</p>

      <div className="tool-links">
        {user ? (
          <>
            <Link to="/chatbot">
              <button>Cyber Awareness Chatbot</button>
            </Link>
            <Link to="/password-checker">
              <button>Password Strength Checker</button>
            </Link>
          </>
        ) : (
          <p>Please <Link to="/login">log in</Link> to access the tools.</p>
        )}
      </div>
    </div>
  );
};

export default Home;
